// Heat diffusion on the GPU.
//
// Usage: deno run --allow-read main.ts <grid-file>
//
// The grid file holds "<width> <height> <steps>" followed by height rows of
// width whole numbers. Each step replaces every cell with
// (4 * self + left + right + up + down) / 8 (integer division), reading the
// previous step's values only; out-of-grid neighbours clamp to the edge cell.

const WORKGROUP = 8;

const SHADER = `
struct Params {
  width: u32,
  height: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(${WORKGROUP}, ${WORKGROUP})
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
  let x = id.x;
  let y = id.y;
  let w = params.width;
  let h = params.height;
  if (x >= w || y >= h) {
    return;
  }

  let xl = select(x - 1u, 0u, x == 0u);
  let xr = min(x + 1u, w - 1u);
  let yu = select(y - 1u, 0u, y == 0u);
  let yd = min(y + 1u, h - 1u);

  let center = src[y * w + x];
  let left = src[y * w + xl];
  let right = src[y * w + xr];
  let up = src[yu * w + x];
  let down = src[yd * w + x];

  dst[y * w + x] = (4u * center + left + right + up + down) / 8u;
}
`;

interface Grid {
  width: number;
  height: number;
  steps: number;
  cells: Uint32Array;
}

async function parseGrid(path: string): Promise<Grid> {
  const text = await Deno.readTextFile(path);
  const tokens = text.split(/\s+/).filter((t) => t.length > 0);
  if (tokens.length < 3) {
    throw new Error("grid file is missing its header");
  }

  const width = Number(tokens[0]);
  const height = Number(tokens[1]);
  const steps = Number(tokens[2]);
  if (!Number.isInteger(width) || width < 1 || width > 512) {
    throw new Error(`invalid width: ${tokens[0]}`);
  }
  if (!Number.isInteger(height) || height < 1 || height > 512) {
    throw new Error(`invalid height: ${tokens[1]}`);
  }
  if (!Number.isInteger(steps) || steps < 0 || steps > 1000) {
    throw new Error(`invalid steps: ${tokens[2]}`);
  }

  const count = width * height;
  if (tokens.length < 3 + count) {
    throw new Error("grid file has fewer cells than its header declares");
  }

  const cells = new Uint32Array(count);
  for (let i = 0; i < count; i++) {
    cells[i] = Number(tokens[3 + i]);
  }
  return { width, height, steps, cells };
}

async function runStencil(grid: Grid): Promise<Uint32Array> {
  const adapter = await navigator.gpu?.requestAdapter();
  if (!adapter) {
    throw new Error("no WebGPU adapter available");
  }
  const device = await adapter.requestDevice();

  try {
    const { width, height, steps, cells } = grid;
    const byteLength = cells.byteLength;

    const usage = GPUBufferUsage.STORAGE |
      GPUBufferUsage.COPY_SRC |
      GPUBufferUsage.COPY_DST;
    const bufferA = device.createBuffer({ size: byteLength, usage });
    const bufferB = device.createBuffer({ size: byteLength, usage });
    const readBuffer = device.createBuffer({
      size: byteLength,
      usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
    });
    const paramsBuffer = device.createBuffer({
      size: 16,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    });

    device.queue.writeBuffer(bufferA, 0, cells);
    device.queue.writeBuffer(
      paramsBuffer,
      0,
      new Uint32Array([width, height, 0, 0]),
    );

    const module = device.createShaderModule({ code: SHADER });
    const pipeline = device.createComputePipeline({
      layout: "auto",
      compute: { module, entryPoint: "main" },
    });

    // Ping-pong: even steps read A and write B, odd steps read B and write A.
    const bindGroups = [bufferA, bufferB].map((_, i) => {
      const src = i === 0 ? bufferA : bufferB;
      const dst = i === 0 ? bufferB : bufferA;
      return device.createBindGroup({
        layout: pipeline.getBindGroupLayout(0),
        entries: [
          { binding: 0, resource: { buffer: paramsBuffer } },
          { binding: 1, resource: { buffer: src } },
          { binding: 2, resource: { buffer: dst } },
        ],
      });
    });

    const encoder = device.createCommandEncoder();
    for (let step = 0; step < steps; step++) {
      const pass = encoder.beginComputePass();
      pass.setPipeline(pipeline);
      pass.setBindGroup(0, bindGroups[step % 2]);
      pass.dispatchWorkgroups(
        Math.ceil(width / WORKGROUP),
        Math.ceil(height / WORKGROUP),
      );
      pass.end();
    }

    const result = steps % 2 === 0 ? bufferA : bufferB;
    encoder.copyBufferToBuffer(result, 0, readBuffer, 0, byteLength);
    device.queue.submit([encoder.finish()]);

    await readBuffer.mapAsync(GPUMapMode.READ);
    const out = new Uint32Array(readBuffer.getMappedRange().slice(0));
    readBuffer.unmap();
    return out;
  } finally {
    device.destroy();
  }
}

function formatOutput(width: number, height: number, cells: Uint32Array): string {
  const lines: string[] = [];
  let sum = 0;
  for (let y = 0; y < height; y++) {
    const row = new Array<number>(width);
    for (let x = 0; x < width; x++) {
      const v = cells[y * width + x];
      row[x] = v;
      sum += v;
    }
    lines.push(row.join(" "));
  }
  lines.push(`SUM ${sum}`);
  return lines.join("\n") + "\n";
}

async function writeAll(text: string): Promise<void> {
  const bytes = new TextEncoder().encode(text);
  let offset = 0;
  while (offset < bytes.length) {
    offset += await Deno.stdout.write(bytes.subarray(offset));
  }
}

async function main(): Promise<void> {
  const path = Deno.args[0];
  if (path === undefined) {
    throw new Error("usage: main.ts <grid-file>");
  }

  const grid = await parseGrid(path);
  const cells = await runStencil(grid);
  await writeAll(formatOutput(grid.width, grid.height, cells));
}

if (import.meta.main) {
  try {
    await main();
  } catch (err) {
    console.error(err instanceof Error ? err.message : err);
    Deno.exit(1);
  }
}
